+    assert.deepEqual(runCli([], { env: { TIMEOUT_SECONDS: raw } }), {
+      status: 0, signal: null,
+      stdout: JSON.stringify({ timeoutMs, format: 'json' }) + '\n', stderr: '',
+    });
+  });
+}
+
+for (const raw of ['0', '00', '61', '061', '999999999999999999999999', '1.5', '+1', '-1', ' 1', '1 ', '1\n', '', 'abc', '1e1', '１']) {
